    static String value(String raw) {
        if (raw == null || raw.trim().isEmpty()) {
            return "unknown";
        }

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < raw.length() && out.length() < MAX_VALUE_LENGTH; i++) {
            char c = raw.charAt(i);

            if (c >= ' ' && c != '\u007f' && c != '=') {
                out.append(c);
            } else if (c == '=') {
                out.append('_');
            }
        }

        return out.length() == 0 ? "unknown" : out.toString();
    }
